import os, base64, zlib
R = "LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R, p)
def rd(p): return open(P(p), encoding="utf-8").read()
def w(p, s): open(P(p), "w", encoding="utf-8").write(s)
def sub(s, old, new, what):
    if old not in s: raise SystemExit("[loi] khong thay doan can sua: " + what)
    return s.replace(old, new, 1)
T = {'looks.js': '', 'orient.js': '', 'looks.css': ''}
V = ''
J = ''
def D(k): return zlib.decompress(base64.b64decode(T[k])).decode("utf-8")
if os.path.exists(P("static/js/looks.js")): raise SystemExit("[loi] da ap dung patch40 roi")
if not os.path.exists(P("static/js/filters.js")): raise SystemExit("[loi] can cai patch36 truoc")
# 1) filter mau dien anh + giu ngang/doc
w("static/js/looks.js", D("looks.js")); w("static/js/orient.js", D("orient.js"))
w("static/polish.css", rd("static/polish.css") + "\n" + D("looks.css"))
h = rd("templates/index.html")
h = sub(h, '  <script src="/static/js/filters.js"></script>', '  <script src="/static/js/looks.js"></script>\n  <script src="/static/js/filters.js"></script>\n  <script src="/static/js/orient.js"></script>', "index script")
w("templates/index.html", h)
# 2) video gioi thieu moi
os.makedirs(P("static/downloads"), exist_ok=True)
open(P("static/downloads/intro2.mp4"), "wb").write(base64.b64decode(V))
open(P("static/downloads/intro2.jpg"), "wb").write(base64.b64decode(J))
n = 0
for root, _, fs in os.walk(R):
    if ".git" in root or "node_modules" in root: continue
    for f in fs:
        if not f.endswith((".html", ".js", ".css")): continue
        p = os.path.join(root, f)
        try: s = open(p, encoding="utf-8").read()
        except Exception: continue
        if "demo.mp4" in s or "demo-poster.jpg" in s:
            open(p, "w", encoding="utf-8").write(s.replace("demo.mp4", "intro2.mp4").replace("demo-poster.jpg", "intro2.jpg")); n += 1
if n == 0: print("[canh bao] khong thay cho gan video cu trong landing, kiem tra lai")
# 3) nhan "Moi cap nhat" canh nut iPhone + the tinh nang
L = rd("templates/landing.html")
if "Mới cập nhật" not in L:
    L = sub(L, '<span>Tải cấu hình cho iPhone</span>', '<span>Tải cấu hình cho iPhone</span><em class="nw upd">Mới cập nhật</em>', "nut iPhone")
if "Filter màu điện ảnh" not in L:
    card = '        <article class="feat-new"><svg class="ic xl"><use href="#i-star"/></svg><h3>Filter màu điện ảnh <em class="nw">Mới</em></h3><p>19 bộ lọc kiểu Kodak, Cinema, Polaroid, Noir, Cyber… có hạt phim, viền tối, ánh sáng tràn. Up ảnh hay video từ thư viện cũng giữ nguyên ngang hay dọc.</p></article>\n'
    k = '        <article class="feat-new"><svg class="ic xl"><use href="#i-star"/></svg><h3>Filter Locket'
    if k in L: L = L.replace(k, card + k, 1)
w("templates/landing.html", L)
c = rd("static/landing.css") + """
/* patch40: nhan Moi cap nhat */
#ios-btn { position: relative; }
.nw.upd { margin-left: 10px; font-style: normal; font-size: .72rem; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; background: #ff4660; color: #fff; padding: 4px 9px; border-radius: 99px; animation: updpulse 1.6s ease-in-out infinite; white-space: nowrap; }
@keyframes updpulse { 0%,100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(255,70,96,.55); } 50% { transform: scale(1.07); box-shadow: 0 0 0 7px rgba(255,70,96,0); } }
"""
w("static/landing.css", c)
print("[ok] patch40 xong: filter dien anh, giu ngang/doc, video moi, nhan Moi cap nhat")
